// Einmaliger Reset 2026-08-01, Nachtrag zum ersten SharepicNeedStage-Reset: diese 4
// Vorgaenge wurden zunaechst bewusst AUSGESCHLOSSEN, weil ihr qaVerdictJson neben
// guard_symbol_drift auch anchors_few_objects zeigte (vermeintlich ein zweites,
// unabhaengiges Problem). Naeher geprueft: concreteCount() in der QA-Agent-Regelpruefung
// schliesst ueber isForbiddenSymbolObject() GENAU dieselben Begriffe aus, die wir bereits
// aus der Klischee-Liste entfernt haben (Sparschwein/Rathaus) - die "zu wenige Objekte"-
// Meldung war also eine Folge DESSELBEN jetzt gelockerten Guards, kein zweites Problem:
//  - vol_10643 (2026/138): ['leeres Sparschwein','Stadtwerke-Schild'] - Sparschwein zaehlte nicht
//  - vol_10650 (2026/143): ['Fenster im Rathaus','Massband','Rathaus-Tuer'] - beide Rathaus-Eintraege zaehlten nicht
//  - vol_10597 (2026/107): ['Sparschwein','Stolperstein'] - Sparschwein zaehlte nicht
//  - vol_10576 (2026/094): ['Sparschwein','Haushaltsentwurf'] - Sparschwein zaehlte nicht
// Nach der Lockerung zaehlen alle wieder mit, jede Zeile hat dann >=2 konkrete Objekte.
// contentStage bewusst nicht angefasst (138/143/107 teils content_posted, 094 offen -
// das ist ein separates, bereits per P3d-Retry-Fix behandeltes Thema).
const TARGETS = [
  { vorgangKey: 'vol_10643', vorgangsnummer: '2026/138' },
  { vorgangKey: 'vol_10650', vorgangsnummer: '2026/143' },
  { vorgangKey: 'vol_10597', vorgangsnummer: '2026/107' },
  { vorgangKey: 'vol_10576', vorgangsnummer: '2026/094' }
];

if (!TARGETS.length) {
  throw new Error('[SharepicNeedStage-Reset2] TARGETS im Node "Konfiguriere Ziele" befuellen.');
}

return TARGETS.map(t => ({
  json: {
    vorgangKey: t.vorgangKey,
    vorgangsnummer: t.vorgangsnummer,
    sharepicNeedStage: 'topic_ok',
    visualPromptStage: 'needs_prompt',
    imageStage: 'not_started',
    visualDecisionReason: 'Manueller Reset 2026-08-01 (Nachtrag): anchors_few_objects war Folge desselben Symbol-Drift-Guards (Sparschwein/Rathaus in concreteCount ausgeschlossen), jetzt gelockert',
    contentErrorReason: '',
    last_error_code: '',
    last_error_message: '',
    last_error_stage: '',
    last_error_at: '',
    next_retry_at: '',
    retry_count: 0
  }
}));
